{
  "ruleset_id": "kulturnyi-grant-gorodskaya-scena",
  "rules": [
    {
      "description": "Руководитель проекта должен быть совершеннолетним (не моложе 18 лет).",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "team.project_lead_age",
        "op": "ge",
        "value": 18
      }
    },
    {
      "description": "Заявитель должен обеспечить не менее 20% бюджета за счёт софинансирования.",
      "severity": "major",
      "category": "co_financing",
      "condition": {
        "field": "budget.co_financing_pct",
        "op": "ge",
        "value": 20
      }
    },
    {
      "description": "Для очных мероприятий требуется согласие площадки.",
      "severity": "major",
      "category": "documents",
      "condition": {
        "field": "documents.venue_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Запрашиваемый грант не должен превышать 1 500 000 рублей.",
      "severity": "critical",
      "category": "grant_amount",
      "condition": {
        "field": "application.requested_rub",
        "op": "le",
        "value": 1500000
      }
    }
  ]
}

{
  "ruleset_id": "additional-education-program",
  "rules": [
    {
      "description": "The organization must have a valid education activity license.",
      "severity": "critical",
      "category": "licensing",
      "condition": {
        "field": "documents.education_license.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The program must comprise at least 72 hours.",
      "severity": "major",
      "category": "duration",
      "condition": {
        "field": "curriculum.total_hours",
        "op": "ge",
        "value": 72
      }
    },
    {
      "description": "At least 80% of teachers must have relevant qualifications.",
      "severity": "major",
      "category": "staffing",
      "condition": {
        "field": "staff.qualified_teachers_pct",
        "op": "ge",
        "value": 80
      }
    },
    {
      "description": "The program may be delivered only in person or in a blended format.",
      "severity": "major",
      "category": "delivery-format",
      "condition": {
        "field": "programme.delivery_format",
        "op": "in",
        "value": [
          "очно",
          "смешанно"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "energy-efficiency-subsidy",
  "rules": [
    {
      "description": "Проект обязан снизить потребление энергии не менее чем на 20%.",
      "severity": "critical",
      "category": "energy_reduction",
      "condition": {
        "field": "project.energy_consumption_reduction_pct",
        "op": "ge",
        "value": 20
      }
    },
    {
      "description": "Доля софинансирования заявителя должна составлять не менее 30%.",
      "severity": "critical",
      "category": "co_financing",
      "condition": {
        "field": "budget.co_financing_pct",
        "op": "ge",
        "value": 30
      }
    },
    {
      "description": "К заявке должен быть приложен технический паспорт объекта.",
      "severity": "critical",
      "category": "documentation",
      "condition": {
        "field": "documents.technical_passport.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Работы должны быть завершены не позднее 31 декабря 2027 года.",
      "severity": "critical",
      "category": "completion_deadline",
      "condition": {
        "field": "project.completion_date",
        "op": "le",
        "value": "2027-12-31"
      }
    }
  ]
}

{
  "ruleset_id": "nordstar-main-grant-track-v2-4",
  "rules": [
    {
      "description": "The applicant must have been registered for at least 24 months.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "org_v2.months_registered",
        "op": "ge",
        "value": 24
      }
    },
    {
      "description": "The requested grant amount must not exceed 250000 euros.",
      "severity": "critical",
      "category": "funding_limit",
      "condition": {
        "field": "org_v2.total_requested",
        "op": "le",
        "value": 250000
      }
    },
    {
      "description": "The application must include an independent audit report for the last completed financial year.",
      "severity": "critical",
      "category": "audit",
      "condition": {
        "field": "documents.audit_report.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The application submission date must be no later than 31 March 2027.",
      "severity": "critical",
      "category": "deadline",
      "condition": {
        "field": "org_v2.submission_date",
        "op": "le",
        "value": "2027-03-31"
      }
    },
    {
      "description": "The employee headcount in the application must match the headcount in the annual report.",
      "severity": "major",
      "category": "consistency",
      "condition": {
        "field": "org_v2.declared_headcount",
        "op": "consistent",
        "value": {
          "fields": [
            "org_v2.declared_headcount",
            "annual_report.headcount"
          ]
        }
      }
    },
    {
      "description": "The annual report must be prepared under IFRS.",
      "severity": "minor",
      "category": "reporting_standard",
      "condition": {
        "field": "annual_report.ifrs",
        "op": "eq",
        "value": true
      }
    }
  ]
}

{
  "ruleset_id": "fond-primer-grant-program-2026",
  "rules": [
    {
      "description": "Организация-заявитель должна быть зарегистрирована не менее 12 месяцев на дату подачи заявки.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "application_form.months_registered",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "Запрашиваемая сумма не должна превышать 100000 евро.",
      "severity": "major",
      "category": "budget_limit",
      "condition": {
        "field": "application_form.requested_total_eur",
        "op": "le",
        "value": 100000
      }
    },
    {
      "description": "Расходы на оборудование не должны превышать 40% общего бюджета.",
      "severity": "major",
      "category": "budget_share",
      "condition": {
        "field": "budget.row.equipment.share_pct",
        "op": "le",
        "value": 40
      }
    },
    {
      "description": "Форма заявки должна присутствовать в полном пакете документов.",
      "severity": "critical",
      "category": "documents",
      "condition": {
        "field": "documents.application_form.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Детализированный бюджет должен присутствовать в полном пакете документов.",
      "severity": "critical",
      "category": "documents",
      "condition": {
        "field": "documents.budget.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Свидетельство о регистрации или выписка из реестра должны присутствовать в полном пакете документов.",
      "severity": "critical",
      "category": "documents",
      "condition": {
        "field": "documents.registration_cert.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Последняя финансовая отчётность должна присутствовать в полном пакете документов.",
      "severity": "critical",
      "category": "documents",
      "condition": {
        "field": "documents.finance_statement.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявка должна быть подана не позднее 1 октября 2026 года включительно.",
      "severity": "major",
      "category": "deadline",
      "condition": {
        "field": "application_form.submission_date",
        "op": "le",
        "value": "2026-10-01"
      }
    },
    {
      "description": "Форма заявки должна быть подписана законным представителем.",
      "severity": "critical",
      "category": "signature",
      "condition": {
        "field": "application_form.signature_present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Запрашиваемая в форме сумма должна точно совпадать с итогом детализированного бюджета.",
      "severity": "major",
      "category": "consistency",
      "condition": {
        "field": "application_form.requested_total_eur",
        "op": "consistent",
        "fields": [
          "application_form.requested_total_eur",
          "budget.totals.total"
        ],
        "value": null
      }
    },
    {
      "description": "Финансовая отчётность должна охватывать FY2025.",
      "severity": "major",
      "category": "reporting_period",
      "condition": {
        "field": "finance_statement.period",
        "op": "eq",
        "value": "FY2025"
      }
    }
  ]
}

{
  "ruleset_id": "capital-repair-program",
  "rules": [
    {
      "description": "Дом должен быть построен не позднее 2005 года.",
      "severity": "critical",
      "category": "building_eligibility",
      "condition": {
        "field": "building.construction_year",
        "op": "le",
        "value": 2005
      }
    },
    {
      "description": "Решение собственников должно быть поддержано не менее чем 66% голосов.",
      "severity": "critical",
      "category": "owner_approval",
      "condition": {
        "field": "owners.approval_pct",
        "op": "ge",
        "value": 66
      }
    },
    {
      "description": "К заявке должен прилагаться акт обследования дефектов.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.defect_report.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявка должна быть подана не позднее 1 апреля 2027 года включительно.",
      "severity": "critical",
      "category": "submission_deadline",
      "condition": {
        "field": "application.submission_date",
        "op": "le",
        "value": "2027-04-01"
      }
    }
  ]
}

{
  "ruleset_id": "lgotnyy-mikrozaem-dlya-msp",
  "rules": [
    {
      "description": "Годовая выручка компании не превышает 120 000 000 рублей.",
      "severity": "critical",
      "category": "revenue_limit",
      "condition": {
        "field": "company.annual_revenue_rub",
        "op": "le",
        "value": 120000000
      }
    },
    {
      "description": "У компании отсутствует просроченная задолженность.",
      "severity": "critical",
      "category": "overdue_debt",
      "condition": {
        "field": "company.overdue_debt",
        "op": "eq",
        "value": false
      }
    },
    {
      "description": "Не менее 51% долей компании принадлежит российским владельцам.",
      "severity": "critical",
      "category": "russian_ownership",
      "condition": {
        "field": "company.russian_ownership_pct",
        "op": "ge",
        "value": 51
      }
    },
    {
      "description": "Сумма займа не превышает 10 000 000 рублей.",
      "severity": "critical",
      "category": "loan_limit",
      "condition": {
        "field": "loan.requested_rub",
        "op": "le",
        "value": 10000000
      }
    }
  ]
}

{
  "ruleset_id": "municipal-subsidy-2026",
  "rules": [
    {
      "description": "Applicant must be registered for at least 12 months.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "applicant.registration_months",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "Requested subsidy must not exceed 5,000,000 rubles.",
      "severity": "critical",
      "category": "amount",
      "condition": {
        "field": "application.requested_rub",
        "op": "le",
        "value": 5000000
      }
    },
    {
      "description": "Application must include financial statements for the last year.",
      "severity": "critical",
      "category": "documentation",
      "condition": {
        "field": "documents.financial_statement.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Application submission date must be no later than September 15, 2026, inclusive.",
      "severity": "critical",
      "category": "deadline",
      "condition": {
        "field": "application.submission_date",
        "op": "le",
        "value": "2026-09-15"
      }
    },
    {
      "description": "Organizations with tax arrears are not admitted.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "applicant.tax_arrears",
        "op": "gt",
        "value": 0
      }
    }
  ]
}

{
  "ruleset_id": "zakupka-remontnykh-rabot",
  "rules": [
    {
      "description": "Годовая выручка поставщика должна быть не менее 10 000 000 рублей.",
      "severity": "critical",
      "category": "financial_eligibility",
      "condition": {
        "field": "supplier.annual_turnover_rub",
        "op": "ge",
        "value": 10000000
      }
    },
    {
      "description": "Для допуска требуется действующее свидетельство СРО.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.sro_certificate.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Участник допускается только со статусом санкционной проверки «clear».",
      "severity": "critical",
      "category": "sanctions",
      "condition": {
        "field": "supplier.sanctions_status",
        "op": "eq",
        "value": "clear"
      }
    },
    {
      "description": "Заявки принимаются не позднее 20 ноября 2026 года.",
      "severity": "critical",
      "category": "submission_deadline",
      "condition": {
        "field": "bid.submission_date",
        "op": "le",
        "value": "2026-11-20"
      }
    }
  ]
}

{
  "ruleset_id": "konkurs-prikladnykh-issledovaniy",
  "rules": [
    {
      "description": "Руководитель должен иметь степень «кандидат наук» или «доктор наук».",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "researcher.degree",
        "op": "in",
        "value": [
          "кандидат наук",
          "доктор наук"
        ]
      }
    },
    {
      "description": "Руководитель должен иметь не менее трёх публикаций в рецензируемых журналах.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "researcher.peer_reviewed_publications",
        "op": "ge",
        "value": 3
      }
    },
    {
      "description": "Должно присутствовать согласие на размещение обезличенных данных исследования.",
      "severity": "major",
      "category": "consent",
      "condition": {
        "field": "documents.open_data_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявленный в форме бюджет должен совпадать с итогом сметы.",
      "severity": "major",
      "category": "budget",
      "condition": {
        "op": "consistent",
        "fields": [
          "application.declared_budget_rub",
          "budget.total_rub"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "social-contract",
  "rules": [
    {
      "description": "The household must be located in Moscow or Moscow Oblast.",
      "severity": "critical",
      "category": "region",
      "condition": {
        "field": "household.region",
        "op": "in",
        "value": [
          "Moscow",
          "Moscow Oblast"
        ]
      }
    },
    {
      "description": "Monthly income per person must not exceed 25,000 rubles.",
      "severity": "critical",
      "category": "income",
      "condition": {
        "field": "household.monthly_income_per_person_rub",
        "op": "le",
        "value": 25000
      }
    },
    {
      "description": "Consent to personal data processing must be present.",
      "severity": "critical",
      "category": "consent",
      "condition": {
        "field": "documents.personal_data_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The applicant must have employment status unemployed or job_seeker.",
      "severity": "critical",
      "category": "employment",
      "condition": {
        "field": "applicant.employment_status",
        "op": "in",
        "value": [
          "unemployed",
          "job_seeker"
        ]
      }
    }
  ]
}
